/// <summary>
/// CB748_PricingConditions
/// </summary>
[ExtensionOf(formDataFieldStr(MarkupTable, MarkupTable, METIsOffRemittance))]
internal final class METMarkupTableFrm_MarkupTableIsOffRemittance_Extension
{
}

Method.Source:
/// <summary>
/// METIsOffRemittance.modified extension
/// </summary>
public void modified()
{
    FormDataObject formDataObject = any2Object(this) as FormDataObject;
    FormDataSource markupTableDS = formDataObject.datasource();
    MarkupTable markupTable = markupTableDS.cursor();

    next modified();

    markupTableDS.object(fieldNum(MarkupTable, METFollowTransactionTaxItemGroup)).allowEdit(markupTable.METIsOffRemittance);

    // Reset METFollowTransactionTaxItemGroup if METIsOffRemittance set to no
    if (!markupTable.METIsOffRemittance)
    {
        markupTable.METFollowTransactionTaxItemGroup = NoYes::No;
    }
}
